    hh, mm = map(int, stdin.readline().strip().split(':'))
    target_time = hh * 60 + mm

    # Find the nearest previous lucky time
    current_time = target_time
    while True:
        if '7' in str(current_time):
            break
        current_time = (current_time - 1) % 1440

    # Calculate the number of snooze presses needed
    snooze_presses = 0
    while current_time != target_time:
        current_time = find_next_lucky_time(current_time, x)
        snooze_presses += 1

    stdout.write(str(snooze_presses) + '\n')

